Repair the following GNU C++ code so that it correctly solves the programming problem. The code reads and writes I/O from the console. Your repaired code should implement the problem correctly, meaning that it should produce the correct output for any valid input.
Print your repaired code and also the confidence score you give to your repair. The confidence score should be a number between 0 and 1. The format of the output should be:
<repaired_code>
<your_repaired_code>
</repaired_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the problem description:
<problem_description>
As behooves any intelligent schoolboy, Kevin Sun is studying psycowlogy, cowculus, and cryptcowgraphy at the Bovinia State University (BGU) under Farmer Ivan. During his Mathematics of Olympiads (MoO) class, Kevin was confronted with a weird functional equation and needs your help. For two fixed integers k and p, where p is an odd prime number, the functional equation states that  for some function . (This equation should hold for any integer x in the range 0 to p - 1, inclusive.)It turns out that f can actually be many different functions. Instead of finding a solution, Kevin wants you to count the number of distinct functions f that satisfy this equation. Since the answer may be very large, you should print your result modulo 109 + 7.
</problem_description>

Here is the GNU C++ code you have to repair:
<original_code>
#include <bits/stdc++.h>
using namespace std;

#define ms(s, n) memset(s, n, sizeof(s))
#define FOR(i, a, b) for(int i = (a); i < (b); i++)
#define FORd(i, a, b) for(int i = (a) - 1; i >= (b); i--)
#define rep(i, a, b) for(int i = (a); i < (b); i++)
#define sz(a) int((a).size())
#define all(a) (a).begin(), (a).end()
#define pb push_back
#define mp make_pair
#define fi first
#define se second
typedef long long ll;
typedef unsigned long long ull;
typedef long double ld;
typedef pair<int, int> pi;
typedef vector<int> vi;
typedef vector<pi> vii;
typedef pair<ll, ll> lll;
ll gcd(ll a, ll b) {ll r; while (b != 0) {r = a % b; a = b; b = r;} return a;}
ll lcm(ll a, ll b) {return a / gcd(a, b) * b;}
#define EPS 1e-9
const int mod = (int) 1e9 + 7;
const int INF = (int) 1e9;
const ll LINF = (ll) 1e18;
const ld PI = 2 * acos(0);
const int M = 50;
const int N = 1e6 + 7;


ll pw(ll x, ll k){
    if (!k) return 1;
    if (k & 1) return x * pw(x, k - 1) % mod;
    ll t = pw(x, k / 2);
    return t * t % mod;
}


ll get(ll x, ll k, ll n){
    if (!k) return 1 % n;
    if (k & 1) return x * get(x, k - 1, n) % n;
    ll t = get(x, k >> 1, n);
    return t * t % n;
}

int n, k;
int a[N];
int check[N];



void solve() {
    cin >> n >> k;
    if (k == 0){
        cout << pw(k, k - 1);
        return;
    }
    if (k == 1){
        cout << pw(k, k);
        return;
    }
    for(int d = 0; d < n; d++){
        a[d] = (ll) d * k % n;
    }
    ll ans = 1;
    for(int d = 0; d < n; d++)
        if (!check[d]){
            check[d] = 1;
            d = a[d];
            int cnt = 1;
            while (!check[d]){
                d = a[d];
                cnt++;
            }
            if (get(k, cnt, n) == 1){
                ans = (ans * n) % mod;
            }
        }
    cout << ans;

}

int main() {
    //ios_base::sync_with_stdio(0); cin.tie(NULL);
#ifndef ONLINE_JUDGE
    freopen("in.txt", "r", stdin); //freopen("out.txt", "w", stdout);
#endif

    solve();
#ifdef _LOCAL_
    //printf("\nTime elapsed: %dms", 1000 * clock() / CLOCKS_PER_SEC);
#endif
    return 0;
}

